+  role: BoardActorRole;
+  residentId: string;
+  displayName: string;
+};
+
+export type BoardCategory = {
+  id: string;
+  name: string;
+  slug: string;
+  sortOrder: number;
+  isActive: boolean;
+};
+
+export type BoardListParams = {
+  categoryId?: string;
+  search?: string;
+  sort?: 'created' | 'latest' | 'comments' | 'reactions';
+  order?: 'asc' | 'desc';
+  cursor?: string;
+  limit?: number;
+};
+
+export type BoardListItem = {
+  id: string;
+  categoryId: string;
+  title: string;
+  contentPreview: string;
+  authorName: string;
+  authorRole: 'admin' | 'manager';
+  createdAt: string;
+  updatedAt: string;
+  editedAt?: string;
+  isPinned: boolean;
+  isMine: boolean;
+  stats: {
+    commentCount: number;
+    reactionCount: number;
+    attachmentCount: number;
+  };
+  reactions?: {
+    like: number;
+    heart: number;
+    check: number;
+    smile: number;
+  };
+  attachments?: Array<{
+    id: string;
+    fileType: 'image' | 'file';
+    fileName: string;
+    fileSize: number;
+    storagePath: string;
+    signedUrl?: string;
+  }>;
+};
+
+export type BoardDetail = {
+  post: {
+    id: string;
+    categoryId: string;
+    title: string;
+    content: string;
+    authorName: string;
+    authorRole: 'admin' | 'manager';
+    createdAt: string;
+    updatedAt: string;
+    editedAt?: string;
+    isPinned: boolean;
+    isMine: boolean;
+  };
+  attachments: Array<{
+    id: string;
+    fileType: 'image' | 'file';
+    fileName: string;
+    fileSize: number;
+    mimeType?: string;
